from __future__ import annotations

import itertools
import json
import math
import platform
import time
from collections import Counter
from collections.abc import Mapping
from functools import lru_cache
from importlib.metadata import PackageNotFoundError, version

import networkx as nx
import numpy as np
from qiskit import QuantumCircuit, transpile
from qiskit.circuit import ParameterVector
from qiskit_aer import AerSimulator
from scipy.optimize import minimize


def build_affinity_graph(graph_vertices, task_affinity_matrix, threshold=0.40):
    """Threshold affinities into an unweighted dependency graph."""
    vertices = list(graph_vertices)
    if not math.isfinite(float(threshold)):
        raise ValueError("threshold must be finite.")

    edges = []
    for u, v in itertools.combinations(vertices, 2):
        forward, reverse = f"{u}-{v}", f"{v}-{u}"
        if forward in task_affinity_matrix:
            affinity = float(task_affinity_matrix[forward])
        elif reverse in task_affinity_matrix:
            affinity = float(task_affinity_matrix[reverse])
        else:
            raise ValueError(f"Missing affinity for {u!r}, {v!r}.")
        if not math.isfinite(affinity):
            raise ValueError("Affinities must be finite.")
        if affinity >= threshold:
            edges.append((u, v))
    return edges


def _positive_integer(name, value):
    if isinstance(value, bool) or not isinstance(value, (int, np.integer)):
        raise ValueError(f"{name} must be a positive integer.")
    if value < 1:
        raise ValueError(f"{name} must be a positive integer.")
    return int(value)


def _parse_reference_partition(reference, vertices):
    """Accept two vertex collections or a vertex-to-group-label mapping."""
    if reference is None:
        return None

    vertex_set = set(vertices)
    if isinstance(reference, Mapping):
        if set(reference) == vertex_set:
            labels = list(dict.fromkeys(reference[v] for v in vertices))
            if len(labels) != 2:
                raise ValueError("The reference must contain exactly two groups.")
            groups = [
                [v for v in vertices if reference[v] == label]
                for label in labels
            ]
        else:
            groups = list(reference.values())
    else:
        groups = list(reference)

    if len(groups) != 2:
        raise ValueError("The reference must contain exactly two groups.")

    groups = [list(group) for group in groups]
    if not groups[0] or not groups[1]:
        raise ValueError("Reference groups must both be nonempty.")

    flattened = groups[0] + groups[1]
    if len(flattened) != len(vertices) or set(flattened) != vertex_set:
        raise ValueError("The reference must contain every vertex exactly once.")
    if abs(len(groups[0]) - len(groups[1])) > 1:
        raise ValueError("The reference must satisfy near-equal group sizes.")

    second_group = set(groups[1])
    return sum(1 << i for i, v in enumerate(vertices) if v in second_group)


def _partition_from_state(state, vertices):
    return [
        [v for i, v in enumerate(vertices) if ((state >> i) & 1) == group]
        for group in (0, 1)
    ]


def _partition_metrics(graph, partition):
    """Use unweighted modularity, normalized cut, and size-balance scores."""
    first, second = map(set, partition)
    cut = sum((u in first) != (v in first) for u, v in graph.edges())
    volume_first = sum(dict(graph.degree(first)).values())
    volume_second = sum(dict(graph.degree(second)).values())

    # A zero-volume group contains no incident edges, hence contributes zero.
    normalized_cut = (
        (cut / volume_first if volume_first else 0.0)
        + (cut / volume_second if volume_second else 0.0)
    )
    modularity = (
        nx.algorithms.community.quality.modularity(
            graph, [first, second], weight=None
        )
        if graph.number_of_edges()
        else 0.0
    )
    imbalance = abs(len(first) - len(second))
    return {
        "modularity_score": float(modularity),
        "normalized_cut_score": float(normalized_cut),
        # For seven tasks, the best attainable value is 6/7, not 1.
        "balance_constraint_score": float(1.0 - imbalance / graph.number_of_nodes()),
        "balance_constraint_satisfied": bool(imbalance <= 1),
        "cut_edges": int(cut),
        "group_sizes": [len(first), len(second)],
    }


def _approximation_ratio(cut, benchmark):
    """
    Minimization convention: returned cut / benchmark cut, ideally 1.

    With a certified optimum, this ratio is >= 1. Define 0/0 as 1.
    Return None for an unavailable denominator or a positive cut divided by zero.
    """
    if benchmark is None:
        return None
    if benchmark == 0:
        return 1.0 if cut == 0 else None
    return float(cut / benchmark)


def _package_versions():
    result = {"python": platform.python_version()}
    for package in ("qiskit", "qiskit-aer", "numpy", "scipy", "networkx"):
        try:
            result[package] = version(package)
        except PackageNotFoundError:
            result[package] = "unknown"
    return result


def solve_graph_partition_qaoa(
    graph_vertices,
    graph_edges,
    known_reference_partition,
    p_layers=2,
    lambda_balance=0.6,
    lambda_cut=4.0,
    opt_shots=512,
    final_shots=2048,
    maxiter=60,
    n_repro_runs=3,
    seed=42,
):
    """
    Run shot-based QAOA with classical balanced-partition postprocessing.

    Groups are constrained to floor(n/2) and ceil(n/2) vertices. This prevents
    trivial empty-group cuts and implements a near-equal scheduling constraint.

    For x_i in {0,1}, z_i = 1 - 2*x_i:
        C(x) = sum_edges (1 - z_i*z_j)/2
        H(x) = lambda_cut*C(x) + lambda_balance*(sum_i z_i)**2.

    Up to an irrelevant identity term, each pair has ZZ coefficient
        J_ij = 2*lambda_balance - (lambda_cut/2)*1[(i,j) is an edge].
    Thus RZZ(2*gamma*J_ij) implements its cost-evolution term.

    The optimizer minimizes the measured penalized energy. Final measurements
    are postselected for near-equal sizes. If no feasible sample occurs, sampled
    states are repaired. A strictly improving balanced one-swap local search
    refines the selected sample. Exact enumeration, when n <= 18, is used only
    to benchmark the output; neither it nor the supplied reference initializes
    or selects the returned solution.

    Reproducibility reports independent seeded restarts, partition agreement,
    objective agreement, and software versions. Runtime is wall-clock seconds.
    """
    start_time = time.perf_counter()

    p_layers = _positive_integer("p_layers", p_layers)
    opt_shots = _positive_integer("opt_shots", opt_shots)
    final_shots = _positive_integer("final_shots", final_shots)
    maxiter = _positive_integer("maxiter", maxiter)
    n_repro_runs = _positive_integer("n_repro_runs", n_repro_runs)

    if isinstance(seed, bool) or not isinstance(seed, (int, np.integer)) or seed < 0:
        raise ValueError("seed must be a nonnegative integer.")
    seed = int(seed)

    lambda_balance = float(lambda_balance)
    lambda_cut = float(lambda_cut)
    if not math.isfinite(lambda_balance) or lambda_balance < 0:
        raise ValueError("lambda_balance must be finite and nonnegative.")
    if not math.isfinite(lambda_cut) or lambda_cut <= 0:
        raise ValueError("lambda_cut must be finite and positive.")

    vertices = list(graph_vertices)
    if len(vertices) < 2 or len(set(vertices)) != len(vertices):
        raise ValueError("At least two distinct, hashable vertices are required.")

    index = {vertex: i for i, vertex in enumerate(vertices)}
    graph = nx.Graph()
    graph.add_nodes_from(vertices)
    for edge in graph_edges:
        pair = tuple(edge)
        if len(pair) != 2:
            raise ValueError("Each edge must have exactly two endpoints.")
        u, v = pair
        if u not in index or v not in index:
            raise ValueError("An edge endpoint is not in graph_vertices.")
        if u == v:
            raise ValueError("Self-loops are not supported.")
        graph.add_edge(u, v)

    n = len(vertices)
    full_mask = (1 << n) - 1
    indexed_edges = [(index[u], index[v]) for u, v in graph.edges()]
    edge_set = {tuple(sorted(edge)) for edge in indexed_edges}
    reference_state = _parse_reference_partition(
        known_reference_partition, vertices
    )

    def canonical(state):
        # Remove the arbitrary group-label symmetry by keeping vertex 0 in A.
        return full_mask ^ state if state & 1 else state

    def feasible(state):
        return abs(n - 2 * state.bit_count()) <= 1

    @lru_cache(maxsize=262144)
    def cut_value(state):
        return sum(
            ((state >> i) ^ (state >> j)) & 1
            for i, j in indexed_edges
        )

    def energy(state):
        return (
            lambda_cut * cut_value(state)
            + lambda_balance * (n - 2 * state.bit_count()) ** 2
        )

    def repair_balance(state):
        """Greedily move vertices until a nearest feasible size is reached."""
        target = n // 2 if state.bit_count() <= n // 2 else (n + 1) // 2
        while state.bit_count() != target:
            remove_one = state.bit_count() > target
            candidates = [
                state ^ (1 << i)
                for i in range(n)
                if bool((state >> i) & 1) == remove_one
            ]
            state = min(candidates, key=lambda s: (cut_value(s), s))
        return canonical(state)

    def refine_by_balanced_swaps(state):
        """Improve cut size without changing either group's cardinality."""
        swaps = 0
        while True:
            current_cut = cut_value(state)
            best_state = state
            best_cut = current_cut
            zero_bits = [i for i in range(n) if not ((state >> i) & 1)]
            one_bits = [i for i in range(n) if (state >> i) & 1]
            for i in zero_bits:
                for j in one_bits:
                    candidate = canonical(state ^ (1 << i) ^ (1 << j))
                    candidate_cut = cut_value(candidate)
                    if candidate_cut < best_cut or (
                        candidate_cut == best_cut
                        and candidate_cut < current_cut
                        and candidate < best_state
                    ):
                        best_state, best_cut = candidate, candidate_cut
            if best_cut >= current_cut:
                return canonical(state), swaps
            state = best_state
            swaps += 1

    simulator = AerSimulator(
        method="statevector",
        max_parallel_threads=1,
        max_parallel_experiments=1,
    )
    gammas = ParameterVector("gamma", p_layers)
    betas = ParameterVector("beta", p_layers)
    parameter_order = list(gammas) + list(betas)

    circuit = QuantumCircuit(n)
    circuit.h(range(n))
    for layer in range(p_layers):
        for i, j in itertools.combinations(range(n), 2):
            coefficient = 2.0 * lambda_balance
            if (i, j) in edge_set:
                coefficient -= lambda_cut / 2.0
            if coefficient != 0.0:
                circuit.rzz(2.0 * coefficient * gammas[layer], i, j)
        for i in range(n):
            circuit.rx(2.0 * betas[layer], i)
    circuit.measure_all()

    transpiler_seed = seed % (2**32)
    compiled = transpile(
        circuit,
        simulator,
        optimization_level=1,
        seed_transpiler=transpiler_seed,
    )
    active_parameters = set(compiled.parameters)

    def measure(parameters, shots, simulator_seed):
        bindings = {
            parameter: float(value)
            for parameter, value in zip(parameter_order, parameters)
            if parameter in active_parameters
        }
        bound = compiled.assign_parameters(bindings, inplace=False)
        counts = simulator.run(
            bound, shots=shots, seed_simulator=int(simulator_seed)
        ).result().get_counts()

        # Qiskit prints q[n-1] ... q[0]; integer bit i therefore labels vertex i.
        return {
            int(bitstring.replace(" ", ""), 2): int(count)
            for bitstring, count in counts.items()
        }

    child_sequences = np.random.SeedSequence(seed).spawn(n_repro_runs)
    run_seeds = [
        int(child.generate_state(1, dtype=np.uint32)[0])
        for child in child_sequences
    ]
    runs = []
    run_states = []

    for run_index, run_seed in enumerate(run_seeds):
        run_start = time.perf_counter()
        rng = np.random.default_rng(run_seed)
        initial_parameters = np.concatenate(
            (
                rng.uniform(0.0, np.pi, p_layers),
                rng.uniform(0.0, np.pi / 2.0, p_layers),
            )
        )
        best_parameters = initial_parameters.copy()
        best_measured_energy = math.inf
        evaluation_count = 0

        def objective(parameters):
            nonlocal best_parameters, best_measured_energy, evaluation_count
            simulator_seed = int(rng.integers(0, 2**31 - 1))
            counts = measure(parameters, opt_shots, simulator_seed)
            measured_energy = sum(
                count * energy(state) for state, count in counts.items()
            ) / sum(counts.values())
            evaluation_count += 1
            if measured_energy < best_measured_energy:
                best_measured_energy = float(measured_energy)
                best_parameters = np.asarray(parameters, dtype=float).copy()
            return float(measured_energy)

        optimization = minimize(
            objective,
            initial_parameters,
            method="COBYLA",
            options={"maxiter": maxiter, "rhobeg": 0.5, "tol": 1e-3},
        )

        final_simulator_seed = int(rng.integers(0, 2**31 - 1))
        counts = measure(best_parameters, final_shots, final_simulator_seed)
        histogram = Counter()
        for state, count in counts.items():
            histogram[canonical(state)] += count

        feasible_histogram = {
            state: count
            for state, count in histogram.items()
            if feasible(state)
        }
        feasible_count = sum(feasible_histogram.values())
        used_repair = not bool(feasible_histogram)

        if feasible_histogram:
            sampled_state = min(
                feasible_histogram,
                key=lambda state: (
                    cut_value(state),
                    -feasible_histogram[state],
                    state,
                ),
            )
        else:
            # This fallback uses measured states only, never a reference solution.
            frequent_states = sorted(
                histogram, key=lambda state: (-histogram[state], state)
            )[:32]
            repaired_states = {repair_balance(state) for state in frequent_states}
            sampled_state = min(
                repaired_states, key=lambda state: (cut_value(state), state)
            )

        final_state, refinement_swaps = refine_by_balanced_swaps(sampled_state)
        partition = _partition_from_state(final_state, vertices)
        metrics = _partition_metrics(graph, partition)

        run_states.append(final_state)
        runs.append(
            {
                "run_index": run_index,
                "seed": run_seed,
                "partition": partition,
                **metrics,
                "penalized_energy": float(energy(final_state)),
                "cut_before_local_refinement": int(cut_value(sampled_state)),
                "feasible_sample_fraction": float(
                    feasible_count / sum(counts.values())
                ),
                "balance_repair_used": used_repair,
                "local_refinement_swaps": refinement_swaps,
                "optimized_parameters": {
                    "gamma": best_parameters[:p_layers].tolist(),
                    "beta": best_parameters[p_layers:].tolist(),
                },
                "best_measured_optimization_energy": best_measured_energy,
                "final_measured_energy": float(
                    sum(count * energy(state) for state, count in counts.items())
                    / sum(counts.values())
                ),
                "objective_evaluations": evaluation_count,
                "optimizer_success": bool(optimization.success),
                "optimizer_message": str(optimization.message),
                "final_simulator_seed": final_simulator_seed,
                "runtime": float(time.perf_counter() - run_start),
            }
        )

    # Freeze the returned candidate before computing any exact benchmark.
    best_run_index = min(
        range(n_repro_runs),
        key=lambda i: (runs[i]["cut_edges"], run_states[i], i),
    )
    best_run = runs[best_run_index]
    best_state = run_states[best_run_index]

    benchmark_start = time.perf_counter()
    reference_cut = (
        int(cut_value(reference_state)) if reference_state is not None else None
    )
    exact_optimum = None
    if n <= 18:
        exact_optimum = graph.number_of_edges()
        for chosen in itertools.combinations(range(n), n // 2):
            state = sum(1 << i for i in chosen)
            # For even n, complements have equal size; examine one orientation.
            if n % 2 == 0 and state & 1:
                continue
            exact_optimum = min(exact_optimum, cut_value(state))
            if exact_optimum == 0:
                break
        exact_optimum = int(exact_optimum)

    benchmark_cut = exact_optimum if exact_optimum is not None else reference_cut
    benchmark_source = (
        "exhaustive_balanced_partition_enumeration"
        if exact_optimum is not None
        else "supplied_reference_partition"
        if reference_cut is not None
        else "unavailable"
    )
    for run in runs:
        run["approximation_ratio"] = _approximation_ratio(
            run["cut_edges"], benchmark_cut
        )

    cuts = np.asarray([run["cut_edges"] for run in runs], dtype=float)
    score_statistics = {}
    for name in (
        "modularity_score",
        "normalized_cut_score",
        "balance_constraint_score",
    ):
        values = np.asarray([run[name] for run in runs], dtype=float)
        score_statistics[name] = {
            "mean": float(values.mean()),
            "std": float(values.std(ddof=0)),
        }

    result = {
        "modularity_score": best_run["modularity_score"],
        "normalized_cut_score": best_run["normalized_cut_score"],
        "balance_constraint_score": best_run["balance_constraint_score"],
        "approximation_ratio": best_run["approximation_ratio"],
        "partition": best_run["partition"],
        "cut_edges": best_run["cut_edges"],
        "inter_group_dependency_links": [
            [u, v]
            for u, v in graph.edges()
            if ((best_state >> index[u]) & 1) != ((best_state >> index[v]) & 1)
        ],
        "group_sizes": best_run["group_sizes"],
        "balance_constraint_satisfied": best_run["balance_constraint_satisfied"],
        "penalized_energy": best_run["penalized_energy"],
        "selected_run_index": best_run_index,
        "graph_vertices": vertices,
        "graph_edges": [list(edge) for edge in graph.edges()],
        "benchmark": {
            "source": benchmark_source,
            "cut_edges": benchmark_cut,
            "optimality_certified": exact_optimum is not None,
            "supplied_reference_cut": reference_cut,
            "supplied_reference_is_optimal": (
                reference_cut == exact_optimum
                if reference_cut is not None and exact_optimum is not None
                else None
            ),
            "runtime": float(time.perf_counter() - benchmark_start),
        },
        "score_definitions": {
            "modularity_score": "Unweighted Newman-Girvan modularity.",
            "normalized_cut_score": (
                "cut/volume(A) + cut/volume(B); zero-volume terms are zero."
            ),
            "balance_constraint_score": (
                "1 - abs(|A|-|B|)/n; maximum is 6/7 for seven tasks."
            ),
            "balance_constraint": "Both groups nonempty; abs(|A|-|B|) <= 1.",
            "approximation_ratio": (
                "Returned cut / benchmark cut; certified optimum gives ratio "
                ">= 1. Define 0/0 as 1; null means unavailable or unbounded. "
                "An uncertified reference gives only a reference-relative ratio."
            ),
            "runtime": (
                "Total wall-clock seconds, including all QAOA restarts, "
                "postprocessing, and benchmarking; excludes module imports."
            ),
        },
        "reproducibility": {
            "master_seed": seed,
            "run_seeds": run_seeds,
            "transpiler_seed": transpiler_seed,
            "n_runs": n_repro_runs,
            "simulator": "qiskit_aer.AerSimulator",
            "simulation_method": "statevector with finite-shot measurements",
            "noise_model": None,
            "max_parallel_threads": 1,
            "optimizer": "SciPy COBYLA",
            "parameters": {
                "p_layers": p_layers,
                "lambda_balance": lambda_balance,
                "lambda_cut": lambda_cut,
                "opt_shots": opt_shots,
                "final_shots": final_shots,
                "maxiter": maxiter,
            },
            "best_partition_agreement": float(
                sum(state == best_state for state in run_states) / n_repro_runs
            ),
            "best_cut_agreement": float(np.mean(cuts == best_run["cut_edges"])),
            "optimal_cut_fraction": (
                float(np.mean(cuts == exact_optimum))
                if exact_optimum is not None
                else None
            ),
            "cut_mean": float(cuts.mean()),
            "cut_std": float(cuts.std(ddof=0)),
            "score_statistics": score_statistics,
            "versions": _package_versions(),
            "note": (
                "Restarts use distinct deterministic seeds. Repeating the same "
                "inputs, seed, software versions, and execution environment "
                "should reproduce sampled results; runtimes are not deterministic. "
                "Different optimal partitions can have identical cut scores."
            ),
            "runs": runs,
        },
    }
    result["runtime"] = float(time.perf_counter() - start_time)
    return result


